import { ISendEventResponse, MatrixClient, Room, RoomStateEvent } from "matrix-js-sdk/src/matrix";
import { defer } from "matrix-js-sdk/src/utils";

import {
    VoiceBroadcastInfoEventContent,
    VoiceBroadcastInfoEventType,
    VoiceBroadcastInfoState,
    VoiceBroadcastRecordingsStore,
    VoiceBroadcastRecording,
    getChunkLength,
    VoiceBroadcastPlaybacksStore,
} from "..";
import { checkVoiceBroadcastPreConditions } from "./checkVoiceBroadcastPreConditions";

const startBroadcast = async (
    room: Room,
    client: MatrixClient,
    recordingsStore: VoiceBroadcastRecordingsStore,
): Promise<VoiceBroadcastRecording> => {
    const { promise, resolve, reject } = defer<VoiceBroadcastRecording>();

    const userId = client.getUserId();

    if (!userId) {
        reject("unable to start voice broadcast if current user is unkonwn");
        return promise;
    }

    let result: ISendEventResponse | null = null;

    const onRoomStateEvents = () => {
        if (!result) return;

        const voiceBroadcastEvent = room.currentState.getStateEvents(VoiceBroadcastInfoEventType, userId);

        if (voiceBroadcastEvent?.getId() === result.event_id) {
            room.off(RoomStateEvent.Events, onRoomStateEvents);
            const recording = new VoiceBroadcastRecording(voiceBroadcastEvent, client);
            recordingsStore.setCurrent(recording);
            recording.start();
            resolve(recording);
        }
    };

    room.on(RoomStateEvent.Events, onRoomStateEvents);

    // XXX Michael W: refactor to live event
    result = await client.sendStateEvent(
        room.roomId,
        VoiceBroadcastInfoEventType,
        {
            device_id: client.getDeviceId(),
            state: VoiceBroadcastInfoState.Started,
            chunk_length: getChunkLength(),
        } as VoiceBroadcastInfoEventContent,
        userId,
    );

    return promise;
};

/**
 * Starts a new Voice Broadcast Recording, if
 * - the user has the permissions to do so in the room
 * - the user is not already recording a voice broadcast
 * - there is no other broadcast being recorded in the room, yet
 * Sends a voice_broadcast_info state event and waits for the event to actually appear in the room state.
 */
export const startNewVoiceBroadcastRecording = async (
    room: Room,
    client: MatrixClient,
    playbacksStore: VoiceBroadcastPlaybacksStore,
    recordingsStore: VoiceBroadcastRecordingsStore,
): Promise<VoiceBroadcastRecording | null> => {
    if (!checkVoiceBroadcastPreConditions(room, client, recordingsStore)) {
        return null;
    }

    // pause and clear current playback (if any)
    playbacksStore.getCurrent()?.pause();
    playbacksStore.clearCurrent();

    return startBroadcast(room, client, recordingsStore);
};
# Checkpoint

Task: Resolve repeated Go live activation and device selection state in VoiceBroadcastPreRecordingPip.

Phase 1: Root cause. The component passes `voiceBroadcastPreRecording.start` directly to `AccessibleButton`; no pending guard or disabled prop exists. `AccessibleButton` defaults to a div and only forwards `disabled` when supplied. Repeated activation can therefore call `start` more than once. The menu already receives the root ref and maps device items to their `MediaDeviceInfo`; the hook's `setDevice` updates its state and `currentDeviceLabel`. The component accepts a nullable device even though the menu emits non-null devices. Current tests cover only single interactions.

Phase 2: Pattern. `VoiceBroadcastRecordingPip` uses the same device hook/menu. The menu's callback is typed `(device: MediaDeviceInfo) => void`; `useAudioDeviceSelection.setDevice` requires `MediaDeviceInfo`. The pre-recording component differs by accepting null and has no initiation state.

Phase 3 hypothesis: A synchronous ref guard plus rendered disabled state over the lifetime of `start()` will prevent repeat calls, including events before React rerenders. A non-null selection callback and menu-open guard will preserve a single menu and hook-driven label updates.
